from typing import List

def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [[1] * (n + 1) for _ in range(n + 1)]
    max_length = 1

    for i in range(1, n + 1):
        for j in range(i - 1, -1, -1):
            diff = abs(nums[i - 1] - nums[j])
            for k in range(i - 1, -1, -1):
                if dp[j][k] == 0 or diff <= dp[j][k]:
                    dp[i][j] = max(dp[i][j], dp[j][k] + 1)
                    max_length = max(max_length, dp[i][j])
                    dp[j][k] = diff

    return max_length

def calculateScore(s: str) -> int:
    score = 0
    mirror = {chr(i): chr(219 - i) for i in range(97, 123)}  # Mapping for a-z to z-a
    unmatched = {ch: [] for ch in mirror.keys()}

    for i, ch in enumerate(s):
        target = mirror[ch]
        if unmatched[target]:
            j = unmatched[target].pop()
            score += (i - j)
        else:
            unmatched[ch].append(i)

    return score

