def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Create adjacency list for the graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))  # Store normal directed edges

    # Binary search for the minimum maximum weight
    left, right = 1, 10**6
    def can_reach_with_max_weight(max_weight):
        out_degree = [0] * n
        queue = []
        for v in range(n):
            for u, w in graph[v]:
                if w <= max_weight:
                    out_degree[v] += 1
                    if out_degree[v] <= threshold:
                        queue.append(v)
        visited = [False] * n
        while queue:
            current = queue.pop()
            if visited[current]:
                continue
            visited[current] = True
            for u, w in graph[current]:
                if w <= max_weight:
                    out_degree[u] -= 1
                    if out_degree[u] < threshold and not visited[u]:
                        queue.append(u)
        return visited[0]  # Check if 0 is reachable

    while left < right:
        mid = (left + right) // 2
        if can_reach_with_max_weight(mid):
            right = mid
        else:
            left = mid + 1

    return left if can_reach_with_max_weight(left) else -1

from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[float('inf')] * 3 for _ in range(2)]
    # Initialize the DP table for the first pair of houses
    for j in range(3):
        dp[0][j] = cost[0][j] + cost[n - 1][(0 + 1) % 3]  # Cost for left and right pairs in the first position

    for i in range(1, n // 2):
        new_dp = [[float('inf')] * 3 for _ in range(3)]
        for prev_left in range(3):
            for prev_right in range(3):
                if prev_left != prev_right:
                    for left_color in range(3):
                        for right_color in range(3):
                            if left_color != prev_left and right_color != prev_right and left_color != right_color:
                                new_dp[left_color][right_color] = min(
                                    new_dp[left_color][right_color],
                                    dp[prev_left][prev_right] + cost[i][left_color] + cost[n - 1 - i][right_color]
                                )
        dp = new_dp

    # Extract the minimum cost from the last dp states
    min_cost = float('inf')
    for j in range(3):
        for k in range(3):
            if j != k:
                min_cost = min(min_cost, dp[j][k])
    return min_cost

